import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, float, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, OctahedronGeometry, CircleGeometry, DirectionalLight, Color } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const cBg0 = colors.gradientStops?.[0]?.hex ?? '#0b0b10';
  const cBg1 = colors.gradientStops?.[1]?.hex ?? '#12121a';
  const cBg2 = colors.gradientStops?.[2]?.hex ?? '#16161d';
  const cPaper = colors.paper ?? '#e8ecf2';
  const cAccent = colors.accent ?? '#ff2a38';
  const cCool = '#9fb0c4'; // spec-named dispersed stop

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- STAGE: gradient backdrop (7x6 @ z=-2.5) ----------
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const vy = uv().y;
  bgMat.colorNode = mix(
    mix(color(cBg0), color(cBg1), smoothstep(0.0, 0.6, vy)),
    color(cBg2),
    smoothstep(0.6, 1.0, vy)
  );
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------- PRISM GROUP ----------
  const prismGroup = new Group();
  prismGroup.rotation.z = (12 * Math.PI) / 180;
  prismGroup.rotation.y = (20 * Math.PI) / 180;
  group.add(prismGroup);

  // Equilateral cross-section, side 1.2 -> circumradius = s / sqrt(3)
  const circumR = 1.2 / Math.sqrt(3);
  const prismGeo = new CylinderGeometry(circumR, circumR, 1.8, 3, 1);
  prismGeo.rotateZ(Math.PI / 2); // axis horizontal
  const prismMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ffffff'),
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    dispersion: 0.18,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    roughness: 0.08,
    metalness: 0.0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color(cPaper),
    attenuationDistance: 2.5
  });
  const prism = new Mesh(prismGeo, prismMat);
  prismGroup.add(prism);
  disposables.push(prismGeo, prismMat);

  // ---------- EMISSIVE CORE (brightest element) ----------
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial({
    color: new Color(cAccent),
    emissive: new Color(cAccent),
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.0
  });
  const core = new Mesh(coreGeo, coreMat);
  prismGroup.add(core);
  disposables.push(coreGeo, coreMat);

  // ---------- BACK RIM LIGHT (cool, behind-left) ----------
  const rim = new DirectionalLight(new Color(cCool), 1.4);
  rim.position.set(-2.2, 1.2, -2.8);
  rim.target = prismGroup;
  group.add(rim);
  group.add(rim.target);

  // ---------- CAUSTIC STREAK (floor, dispersed gradient) ----------
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const vx = uv().x;
  causticMat.colorNode = mix(
    mix(color(cAccent), color(cPaper), smoothstep(0.2, 0.5, vx)),
    color(cCool),
    smoothstep(0.5, 0.8, vx)
  );
  causticMat.opacityNode = float(0.35)
    .mul(smoothstep(0.0, 0.15, vx))
    .mul(smoothstep(1.0, 0.85, vx))
    .mul(smoothstep(0.0, 0.3, uv().y))
    .mul(smoothstep(1.0, 0.7, uv().y));
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.2);
  group.add(caustic);
  disposables.push(causticGeo, causticMat);

  // ---------- CONTACT SHADOW (radial, under subject) ----------
  const shadowGeo = new CircleGeometry(1.3, 40);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color('#000000');
  const d = uv().distance(vec2(0.5, 0.5));
  shadowMat.opacityNode = float(0.5).mul(smoothstep(0.5, 0.05, d));
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.12, 0.15);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- TEXT ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1];

  if (headlineItem) {
    const h = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: cPaper,
      align: 'center'
    });
    h.position.set(0, -1.75, 0.4);
    group.add(h);
  }
  if (captionItem) {
    const c = ctx.fontAtlas.createText(String(captionItem.text), {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: cPaper,
      align: 'center',
      letterSpacingPx: 1.44
    });
    c.position.set(0, -2.25, 0.4);
    group.add(c);
  }

  // ---------- CINEMATIC PRIMITIVES ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const handle = fn(prismGroup, p.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------- ENTRANCE: rise-in + weighted settle ----------
  const enterTl = gsap.timeline();
  enterTl.from(prismGroup.position, { y: -0.35, duration: 0.7, ease: 'power3.out' }, 0);
  enterTl.fromTo(
    prismGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.5
  );
  timelines.push(enterTl);

  // ---------- IDLE: one slow transform (core rotation) ----------
  const idleTl = gsap.timeline({ repeat: -1 });
  idleTl.to(core.rotation, { y: Math.PI * 2, duration: 10, ease: 'none' });
  timelines.push(idleTl);

  // ---------- INTERACTION ----------
  group.userData.handlers = {
    pointerover: () => {
      gsap.to(caustic.scale, { x: 1.08, duration: 0.35, ease: 'power2.out' });
    },
    pointerout: () => {
      gsap.to(caustic.scale, { x: 1.0, duration: 0.5, ease: 'power2.out' });
      const settle = gsap.timeline();
      settle.to(prismGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.2, ease: 'power2.out' });
      settle.to(prismGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
      timelines.push(settle);
    }
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(prismGroup.position);
    gsap.killTweensOf(prismGroup.scale);
    gsap.killTweensOf(core.rotation);
    gsap.killTweensOf(caustic.scale);
    for (const h of primHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const r of disposables) {
      if (r && typeof r.dispose === 'function') r.dispose();
    }
    rim.dispose?.();
  };

  return group;
}
